-- Four source-compatible native visuals: three missing generic templates and Fel FireBomb.
-- Requires2026_10_05_03 schema and rebuilt core. No quest-dependent visual rows are imported.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_visual_guard`, `_1kycore_visual_templates`, `_1kycore_visual_addons`, `_1kycore_visual_spawns`;
CREATE TEMPORARY TABLE `_1kycore_visual_guard` (ok INT PRIMARY KEY);
CREATE TEMPORARY TABLE `_1kycore_visual_templates` LIKE `gameobject_template`;
CREATE TEMPORARY TABLE `_1kycore_visual_addons` LIKE `gameobject_template_addon`;
CREATE TEMPORARY TABLE `_1kycore_visual_spawns` LIKE `gameobject`;
UPDATE gameobject_template a JOIN `_1kycore_visual_templates` n ON a.entry=n.entry SET a.`type`=n.`type`,a.`displayId`=n.`displayId`,a.`name`=n.`name`,a.`IconName`=n.`IconName`,a.`castBarCaption`=n.`castBarCaption`,a.`unk1`=n.`unk1`,a.`size`=n.`size`,a.`Data0`=n.`Data0`,a.`Data1`=n.`Data1`,a.`Data2`=n.`Data2`,a.`Data3`=n.`Data3`,a.`Data4`=n.`Data4`,a.`Data5`=n.`Data5`,a.`Data6`=n.`Data6`,a.`Data7`=n.`Data7`,a.`Data8`=n.`Data8`,a.`Data9`=n.`Data9`,a.`Data10`=n.`Data10`,a.`Data11`=n.`Data11`,a.`Data12`=n.`Data12`,a.`Data13`=n.`Data13`,a.`Data14`=n.`Data14`,a.`Data15`=n.`Data15`,a.`Data16`=n.`Data16`,a.`Data17`=n.`Data17`,a.`Data18`=n.`Data18`,a.`Data19`=n.`Data19`,a.`Data20`=n.`Data20`,a.`Data21`=n.`Data21`,a.`Data22`=n.`Data22`,a.`Data23`=n.`Data23`,a.`Data24`=n.`Data24`,a.`Data25`=n.`Data25`,a.`Data26`=n.`Data26`,a.`Data27`=n.`Data27`,a.`Data28`=n.`Data28`,a.`Data29`=n.`Data29`,a.`Data30`=n.`Data30`,a.`Data31`=n.`Data31`,a.`Data32`=n.`Data32`,a.`RequiredLevel`=n.`RequiredLevel`,a.`AIName`=n.`AIName`,a.`ScriptName`=n.`ScriptName` WHERE a.entry=267180 AND a.displayId=0;
DROP TEMPORARY TABLE `_1kycore_visual_guard`, `_1kycore_visual_templates`, `_1kycore_visual_addons`, `_1kycore_visual_spawns`;
