ND a.`Data10` <=> 0 AND a.`Data11` <=> 0 AND a.`Data12` <=> 0 AND a.`Data13` <=> 0 AND a.`Data14` <=> 0 AND a.`Data15` <=> 0 AND a.`Data16` <=> 0 AND a.`Data17` <=> 0 AND a.`Data18` <=> 0 AND a.`Data19` <=> 0 AND a.`Data20` <=> 0 AND a.`Data21` <=> 0 AND a.`Data22` <=> 0 AND a.`Data23` <=> 0 AND a.`Data24` <=> 0 AND a.`Data25` <=> 0 AND a.`Data26` <=> 0 AND a.`Data27` <=> 0 AND a.`Data28` <=> 0 AND a.`Data29` <=> 0 AND a.`Data30` <=> 0 AND a.`Data31` <=> 0 AND a.`Data32` <=> 0 AND a.`RequiredLevel` <=> 0 AND BINARY a.`AIName` <=> BINARY '' AND BINARY a.`ScriptName` <=> BINARY '') LIMIT 1;
