INSERT INTO `_1kycore_visual_guard` SELECT 1 FROM `gameobject` a JOIN `_1kycore_visual_spawns` n ON a.`guid`=n.`guid` WHERE NOT (a.`id` <=> n.`id` AND a.`map` <=> n.`map` AND a.`zoneId` <=> n.`zoneId` AND a.`areaId` <=> n.`areaId` AND BINARY a.`spawnDifficulties` <=> BINARY n.`spawnDifficulties` AND a.`phaseUseFlags` <=> n.`phaseUseFlags` AND a.`PhaseId` <=> n.`PhaseId` AND a.`PhaseGroup` <=> n.`PhaseGroup` AND a.`terrainSwapMap` <=> n.`terrainSwapMap` AND ABS(a.`position_x`-n.`position_x`)<=0.000001 AND ABS(a.`position_y`-n.`position_y`)<=0.000001 AND ABS(a.`position_z`-n.`position_z`)<=0.000001 AND ABS(a.`orientation`-n.`orientation`)<=0.000001 AND a.`spawntimesecs` <=> n.`spawntimesecs` AND ABS(a.`rotation0`-n.`rotation0`)<=0.000001 AND ABS(a.`rotation1`-n.`rotation1`)<=0.000001 AND ABS(a.`rotation2`-n.`rotation2`)<=0.000001 AND ABS(a.`rotation3`-n.`rotation3`)<=0.000001 AND a.`animprogress` <=> n.`animprogress` AND a.`state` <=> n.`state` AND a.`isActive` <=> n.`isActive` AND BINARY a.`ScriptName` <=> BINARY n.`ScriptName`) LIMIT 1;
INSERT INTO `_1kycore_visual_guard` SELECT 1 FROM gameobject_questitem WHERE GameObjectEntry IN (245100,245347,247227,267180) LIMIT 1;
INSERT INTO `_1kycore_visual_guard` SELECT 1 FROM smart_scripts WHERE source_type=1 AND (entryorguid IN (245100,245347,247227,267180) OR entryorguid IN (SELECT -CAST(guid AS SIGNED) FROM `_1kycore_visual_spawns`) OR entryorguid IN (SELECT -CAST(guid AS SIGNED) FROM gameobject WHERE id=267180)) LIMIT 1;
INSERT INTO `_1kycore_visual_guard` SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM quest_template WHERE ID=45629);
INSERT INTO `_1kycore_visual_guard` SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM quest_objectives WHERE `ID`=288263 AND `QuestID`=45629 AND `Type`=2 AND `StorageIndex`=2 AND `ObjectID`=267180 AND `Amount`=4 AND `Flags`=2 AND `Flags2`=0);
INSERT INTO `_1kycore_visual_guard` SELECT 1 FROM gameobject_template a JOIN `_1kycore_visual_templates` n ON a.entry=n.entry LEFT JOIN gameobject_template_addon d ON a.entry=d.entry WHERE a.displayId=n.displayId AND d.entry IS NULL LIMIT 1;
INSERT INTO `gameobject_template_addon` (`entry`,`faction`,`flags`,`mingold`,`maxgold`,`WorldEffectID`,`SpellVisualID`,`SpellStateVisualID`,`StateWorldEffectID`) SELECT n.`entry`,n.`faction`,n.`flags`,n.`mingold`,n.`maxgold`,n.`WorldEffectID`,n.`SpellVisualID`,n.`SpellStateVisualID`,n.`StateWorldEffectID` FROM `_1kycore_visual_addons` n LEFT JOIN `gameobject_template_addon` a ON a.`entry`=n.`entry` WHERE a.`entry` IS NULL;
INSERT INTO `gameobject_template` (`entry`,`type`,`displayId`,`name`,`IconName`,`castBarCaption`,`unk1`,`size`,`Data0`,`Data1`,`Data2`,`Data3`,`Data4`,`Data5`,`Data6`,`Data7`,`Data8`,`Data9`,`Data10`,`Data11`,`Data12`,`Data13`,`Data14`,`Data15`,`Data16`,`Data17`,`Data18`,`Data19`,`Data20`,`Data21`,`Data22`,`Data23`,`Data24`,`Data25`,`Data26`,`Data27`,`Data28`,`Data29`,`Data30`,`Data31`,`Data32`,`RequiredLevel`,`AIName`,`ScriptName`,`VerifiedBuild`) SELECT n.`entry`,n.`type`,n.`displayId`,n.`name`,n.`IconName`,n.`castBarCaption`,n.`unk1`,n.`size`,n.`Data0`,n.`Data1`,n.`Data2`,n.`Data3`,n.`Data4`,n.`Data5`,n.`Data6`,n.`Data7`,n.`Data8`,n.`Data9`,n.`Data10`,n.`Data11`,n.`Data12`,n.`Data13`,n.`Data14`,n.`Data15`,n.`Data16`,n.`Data17`,n.`Data18`,n.`Data19`,n.`Data20`,n.`Data21`,n.`Data22`,n.`Data23`,n.`Data24`,n.`Data25`,n.`Data26`,n.`Data27`,n.`Data28`,n.`Data29`,n.`Data30`,n.`Data31`,n.`Data32`,n.`RequiredLevel`,n.`AIName`,n.`ScriptName`,n.`VerifiedBuild` FROM `_1kycore_visual_templates` n LEFT JOIN `gameobject_template` a ON a.`entry`=n.`entry` WHERE a.`entry` IS NULL;
INSERT INTO `gameobject` (`guid`,`id`,`map`,`zoneId`,`areaId`,`spawnDifficulties`,`phaseUseFlags`,`PhaseId`,`PhaseGroup`,`terrainSwapMap`,`position_x`,`position_y`,`position_z`,`orientation`,`spawntimesecs`,`rotation0`,`rotation1`,`rotation2`,`rotation3`,`animprogress`,`state`,`isActive`,`ScriptName`,`VerifiedBuild`) SELECT n.`guid`,n.`id`,n.`map`,n.`zoneId`,n.`areaId`,n.`spawnDifficulties`,n.`phaseUseFlags`,n.`PhaseId`,n.`PhaseGroup`,n.`terrainSwapMap`,n.`position_x`,n.`position_y`,n.`position_z`,n.`orientation`,n.`spawntimesecs`,n.`rotation0`,n.`rotation1`,n.`rotation2`,n.`rotation3`,n.`animprogress`,n.`state`,n.`isActive`,n.`ScriptName`,n.`VerifiedBuild` FROM `_1kycore_visual_spawns` n LEFT JOIN `gameobject` a ON a.`guid`=n.`guid` WHERE a.`guid` IS NULL;
